class EAaConfigRadSettingType(object):
    EAaConfigRadSettingType_Factory = 0  # Factory defaults currently same as "FactoryAllDomains"
    EAaConfigRadSettingType_Dynamic = 1  # Change dynamic values
    EAaConfigRadSettingType_Persistent = 2  # Write values to file
    EAaConfigRadSettingType_FactoryAllDomains = 3  # Factory defaults all domains
    EAaConfigRadSettingType_PersistentOverOneReset = 4  # BASE0017_08: write values to OneReset file


class EAaConfigRadParamStatus(object):
    EAaConfigRadParamStatus_Ok = 0
    EAaConfigRadParamStatus_OutOfRange = 1
    EAaConfigRadParamStatus_Timeout = 2
    EAaConfigRadParamStatus_Error = 3


class SAaConfigRadParams(Structure):
    _fields_ = [
        ('index', u32),  # index of R&D parameter
        ('size', u32),  # size of R&D parameter
        ('value', u32),  # value of R&D parameter
    ]


@register_message
class SAaConfigSetRadParamsReq(RequestMessage):
    id = 0x2011

    _fields_ = [
        ('header', SMessageHeader),
        ('domain', u32),  # Default value = 7
        ('settingType', u32),  # Default value = 1
        ('noOfParams', u32),
        ('params', SAaConfigRadParams * 2)
    ]

    def __init__(self, board, cpu, *args, **kwargs):
        super(SAaConfigSetRadParamsReq, self).__init__(board, cpu, *args, **kwargs)
        self.header.receiver.task = TASK_RND_PARAMS

        self.domain = ERadDomain.ERadDomain_DSPRake
        self.settingType = EAaConfigRadSettingType.EAaConfigRadSettingType_Dynamic


@register_message
class SAaConfigSetRadParamsResp(ResponseMessage):
    id = 0x2012

    _fields_ = [
        ('header', SMessageHeader),
        ('domain', u32),
        ('paramState', u32)
    ]


@register_message
class SAaConfigGetRadParamsReq(RequestMessage):
    id = 0x2013

    _fields_ = [
        ('header', SMessageHeader),
        ('domain', u32)
    ]


@register_message
class SAaConfigGetRadParamsResp(ResponseMessage):
    id = 0x2014

    _fields_ = [
        ('header', SMessageHeader),
        ('domain', u32),
        ('noOfParams', u32),
        ('params', SAaConfigRadParams * 2)
    ]


class SAaConfigSetRadParamsQuery(Query):
    def __init__(self, req, resp):
        super(SAaConfigSetRadParamsQuery, self).__init__(req, resp)

        self.domain = None  # type: int
        self.param_state = None  # type: int

    def _handle_response(self):
        self.domain = self.resp_msg.domain
        self.param_state = self.resp_msg.paramState

    def fill_req_msg(self, rake_trace_mask=EMPTY_VALUE, rake_trace_user_id=1):
        # type: (int, int) -> None

        if rake_trace_mask != EMPTY_VALUE and rake_trace_user_id != EMPTY_VALUE:
            self.req_msg.noOfParams = PARAM_COUNT_TWO
            self.req_msg.params[0].index = 0
            self.req_msg.params[0].size = DEFAULT_INDEX_SIZE
            self.req_msg.params[0].value = rake_trace_mask
            self.req_msg.params[1].index = 1
            self.req_msg.params[1].size = DEFAULT_INDEX_SIZE
            self.req_msg.params[1].value = rake_trace_user_id

        if rake_trace_mask != EMPTY_VALUE and rake_trace_user_id == EMPTY_VALUE:
            self.req_msg.noOfParams = 1
            self.req_msg.params[0].index = 0
            self.req_msg.params[0].size = DEFAULT_INDEX_SIZE
            self.req_msg.params[0].value = rake_trace_mask

        if rake_trace_mask == EMPTY_VALUE and rake_trace_user_id != EMPTY_VALUE:
            self.req_msg.params[1].index = 1
            self.req_msg.params[1].size = DEFAULT_INDEX_SIZE
            self.req_msg.params[1].value = rake_trace_user_id


class SAaConfigGetRadParamsQuery(Query):
    def __init__(self, req, resp):
        super(SAaConfigGetRadParamsQuery, self).__init__(req, resp)
        self.params = []

    def _handle_response(self):
        self.params = self.resp_msg.parms

