class ConfigurableRadParamsInterface(object):
    def __init__(self, connection):
        self.connection = connection

    def set_rake_config_params(self, rake_trace_mask=EMPTY_VALUE, rake_trace_user_id=EMPTY_VALUE):
        # type: (int, int) -> None

        if rake_trace_mask == EMPTY_VALUE and rake_trace_user_id == EMPTY_VALUE:
            LOGGER.warning('rake_trace_mask == rake_trace_user_id == {}!'.format(EMPTY_VALUE))
            return

        # ???
        if rake_trace_mask < 0:
            rake_trace_mask = 0x7c0  # 1984

        if rake_trace_user_id < 0:
            rake_trace_user_id = 0

        query = SAaConfigSetRadParamsQuery(
            SAaConfigSetRadParamsReq(DEFAULT_BOARD, DEFAULT_CPU),
            SAaConfigSetRadParamsResp()
        )
        query.fill_req_msg(rake_trace_mask, rake_trace_user_id)

        qm = BasicQueryManager(query, self.connection)
        qm.send_request_and_wait_for_response()

        status = query.param_state
        if status != 0:
            LOGGER.warning('Set RaD params ERROR, status {}'.format(status))
        else:
            LOGGER.info('Set RaD params OK, status {}'.format(status))

        sleep(2)
